import { ReceiptError, RpcRejection } from '../_shared/errors.ts';
import { callRpc, defaultRuntime, handleReceiptRequest, isUuid, readBoundedBody, requestBackend, serve, serviceHeaders } from '../_shared/http.ts';
import type { ReceiptContext, ReceiptRuntime } from '../_shared/http.ts';
import { MAX_RECEIPT_BYTES, validateReceiptBytes } from '../_shared/receipt-validation.ts';

interface FinalizedExpense { expense: { receiptId: string | null }; [key: string]: unknown }

async function removeOwnUpload(context: ReceiptContext, objectPath: string): Promise<void> {
  // The path is generated by this invocation and is never taken from request/RPC data.
  try {
    await requestBackend(context, `${context.config.url}/storage/v1/object/receipts`, {
      method: 'DELETE', headers: { ...serviceHeaders(context.config), 'Content-Type': 'application/json' }, body: JSON.stringify({ prefixes: [objectPath] }),
    });
  } catch { /* Best effort: orphan cleanup must never mask the original result. */ }
}

export async function handleUpload(request: Request, runtime: ReceiptRuntime = defaultRuntime): Promise<Response> {
  return handleReceiptRequest(request, runtime, async (context) => {
    const contentType = request.headers.get('Content-Type') ?? '';
    if (!/^multipart\/form-data\s*;/i.test(contentType)) throw new ReceiptError('UPLOAD_INVALID');
    const body = await readBoundedBody(request, MAX_RECEIPT_BYTES + 64 * 1024, 'UPLOAD_INVALID');
    let form: FormData;
    try { form = await new Response(body.buffer as ArrayBuffer, { headers: { 'Content-Type': contentType } }).formData(); }
    catch { throw new ReceiptError('UPLOAD_INVALID'); }
    const allowed = ['draftId', 'expectedRevision', 'idempotencyKey', 'file'];
    if ([...form.keys()].some((key) => !allowed.includes(key)) || allowed.some((key) => form.getAll(key).length !== 1)) throw new ReceiptError('VALIDATION');
    const draftId = form.get('draftId');
    const revision = form.get('expectedRevision');
    const idempotencyKey = form.get('idempotencyKey');
    const file = form.get('file');
    if (!isUuid(draftId) || typeof revision !== 'string' || !/^\d+$/.test(revision) || !Number.isSafeInteger(Number(revision)) || Number(revision) > 2_147_483_647 || typeof idempotencyKey !== 'string' || idempotencyKey.length < 1 || idempotencyKey.length > 200 || idempotencyKey.trim() !== idempotencyKey || /[\u0000-\u001f\u007f]/.test(idempotencyKey)) throw new ReceiptError('VALIDATION');
    if (!(file instanceof File) || file.size === 0 || file.size > MAX_RECEIPT_BYTES) throw new ReceiptError('UPLOAD_INVALID');
    const bytes = new Uint8Array(await file.arrayBuffer());
    const validated = validateReceiptBytes(bytes, file.type);
    const preflight = await callRpc<{ ok: boolean }>(context, 'ledger_receipt_preflight', { p_actor_id: context.actorId, p_draft_id: draftId });
    if (preflight?.ok !== true) throw new ReceiptError('FORBIDDEN');
    const sha256 = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)), (value) => value.toString(16).padStart(2, '0')).join('');
    const receiptId = crypto.randomUUID();
    const objectPath = `${crypto.randomUUID()}.${validated.extension}`;
    let uploaded = false;
    let finalizationStarted = false;
    try {
      const upload = await requestBackend(context, `${context.config.url}/storage/v1/object/receipts/${objectPath}`, {
        method: 'POST', headers: { ...serviceHeaders(context.config), 'Content-Type': validated.mimeType, 'x-upsert': 'false', 'Cache-Control': 'max-age=0' }, body: bytes,
      });
      if (!upload.ok) throw new ReceiptError('BACKEND_UNAVAILABLE');
      uploaded = true;
      finalizationStarted = true;
      const result = await callRpc<FinalizedExpense>(context, 'ledger_receipt_finalize', {
        p_actor_id: context.actorId, p_draft_id: draftId, p_expected_revision: Number(revision), p_idempotency_key: idempotencyKey,
        p_receipt_id: receiptId, p_object_path: objectPath, p_mime_type: validated.mimeType, p_size_bytes: bytes.byteLength, p_sha256: sha256,
      });
      if (!result || !result.expense || !isUuid(result.expense.receiptId)) throw new ReceiptError('BACKEND_UNAVAILABLE');
      if (result.expense.receiptId !== receiptId) await removeOwnUpload(context, objectPath);
      return result;
    } catch (error) {
      // A transport timeout can follow a committed RPC. Never delete a potentially referenced receipt.
      if (uploaded && (!finalizationStarted || error instanceof RpcRejection)) await removeOwnUpload(context, objectPath);
      throw error;
    }
  });
}

serve(handleUpload);
